def _load_application():
    root=Path(tempfile.mkdtemp(prefix="aneira_emotions_integrated_"))
    with zipfile.ZipFile(io.BytesIO(base64.b85decode("".join(_PAYLOAD)))) as archive:
        archive.extractall(root)
    sys.path.insert(0,str(root))
    spec=importlib.util.spec_from_file_location("aneira_emotions_live",root/"main.py")
    module=importlib.util.module_from_spec(spec)
    sys.modules[spec.name]=module
    spec.loader.exec_module(module)
    return module.app
app=_load_application()
